def solve_grid(n: int, r: str, c: str) -> Optional[List[str]]:
    if len(r) != n or len(c) != n:
        return None

    def is_valid(grid, row, col):
        return all(grid[row][i] == '.' for i in range(col)) and all(grid[i][col] == '.' for i in range(row))

    def backtrack(row=0, col=0):
        if row == n:
            return True
        if col == n:
            return backtrack(row + 1, 0)

        for char in ['A', 'B', 'C']:
            if char == r[row] and char == c[col] and is_valid(grid, row, col):
                grid[row] = grid[row][:col] + char + grid[row][col+1:]
                if backtrack(row, col + 1):
                    return True
                grid[row] = grid[row][:col] + '.' + grid[row][col+1:]
        return False

    grid = [['.' for _ in range(n)] for _ in range(n)]
    if not backtrack():
        return None

    return [ ''.join(row) for row in grid ]

def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    width = C - A
    height = D - B
    black_region_width = width // 2
    black_region_height = height // 2
    if (A + B) % 2 == 0:
        black_region_width += 1
    if (A + D) % 2 == 0:
        black_region_height += 1
    return 2 * black_region_width * black_region_height

from heapq import heappop, heappush

def kth_smallest_amount(coins: List[int], k: int) -> int:
    min_heap = [coin for coin in coins]
    seen = set(min_heap)
    while True:
        current_min = heappop(min_heap)
        k -= 1
        if k == 0:
            return current_min
        next_value = current_min + 1
        for coin in coins:
            new_value = next_value * coin
            if new_value not in seen:
                seen.add(new_value)
                heappush(min_heap, new_value)

