def count_good_sequences(N: int, M: int) -> int:
    MOD = 998244353

    def sum_of_divisors(x):
        total = 0
        for i in range(1, int(x**0.5) + 1):
            if x % i == 0:
                total += i
                if i != x // i:
                    total += x // i
        return total

    good_numbers = [i for i in range(1, N + 1) if sum_of_divisors(i) % 3 == 0]
    dp = [[0] * (M + 1) for _ in range(len(good_numbers) + 1)]
    dp[0][0] = 1

    for i in range(1, len(good_numbers) + 1):
        for j in range(1, M + 1):
            dp[i][j] = dp[i - 1][j]
            if j >= good_numbers[i - 1]:
                dp[i][j] += dp[i][j - good_numbers[i - 1]]
                dp[i][j] %= MOD

    return dp[len(good_numbers)][M]

from math import gcd

MOD = 998244353

# Helper function to calculate factorial modulo MOD
def factorial_mod(n, mod=MOD):
    if n == 0 or n == 1:
        return 1
    result = 1
    for i in range(2, n + 1):
        result = (result * i) % mod
    return result

# Helper function to calculate modular inverse using Fermat's Little Theorem
def mod_inverse(a, mod=MOD):
    return pow(a, mod - 2, mod)

# Helper function to calculate binomial coefficient modulo MOD
def binom_mod(n, k, mod=MOD):
    if k > n:
        return 0
    num = factorial_mod(n, mod)
    den = (factorial_mod(k, mod) * factorial_mod(n - k, mod)) % mod
    return (num * mod_inverse(den, mod)) % mod

# Main function to calculate the sum of scores of all good sequences modulo MOD
def sum_of_scores(n: int, m: int) -> int:
    total_sum = 0
    for k in range(1, n + 1):
        current_sum = 0
        for i in range(1, m + 1):
            power = pow(i, k, MOD)
            divisors = power // (i ** (gcd(power, i) - 1))
            current_sum += divisors * binom_mod(divisors, k - 1)
            current_sum %= MOD
        total_sum += current_sum
        total_sum %= MOD
    return total_sum

import itertools

def count_k_palindromic_numbers(n: int, k: int) -> int:
    if n % 2 != 0 and k % 2 == 0:
        return 0
    half_length = n // 2
    half_digits = [str(i) for i in range(1, 10)]
    def is_valid(s):
        count = [s.count(str(i)) for i in range(10)]
        return all(c % 2 == 0 for c in count)
    count = 0
    for half in itertools.product(half_digits, repeat=half_length):
        full = ''.join(half) + (''.join(half[::-1]) if n % 2 == 0 else half[-2::-1])
        num = int(full)
        if num % k == 0 and is_valid(str(num)):
            count += 1
    return count

def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    def find_tile(x, y):
        i = x // K
        j = y // K
        k = y % K if (i + j) % 2 == 0 else x % K
        return i, j, k

    si, sj, sk = find_tile(S_x, S_y)
    ti, tj, tk = find_tile(T_x, T_y)

    # Calculate horizontal and vertical distance between tiles
    horizontal_distance = abs(si - ti)
    vertical_distance = abs(sj - tj)

    # Adjust for the case where the starting tile and target tile are in the same row/column
    if horizontal_distance == 0 and vertical_distance == 0:
        if (sk > tk and (si + sj) % 2 == 0) or (sk < tk and (si + sj) % 2 != 0):
            vertical_distance += 1
    elif horizontal_distance == 0 and vertical_distance == 1:
        if (sk == tk and (si + sj) % 2 != 0) or (sk == tk and (si + sj) % 2 == 0):
            horizontal_distance += 1
    elif horizontal_distance == 1 and vertical_distance == 0:
        if (sk == tk and (si + sj) % 2 != 0) or (sk == tk and (si + sj) % 2 == 0):
            vertical_distance += 1

    return horizontal_distance + vertical_distance

