def expected_operations(N: int, M: int) -> int:
    MOD = 998244353

    @lru_cache(None)
    def dp(x, y):
        if x == N * M:
            return 0
        neighbors = [(x + 1, y), (max(x - N, 0), y)]
        return (len(neighbors) + sum(dp(nx, ny) for nx, ny in neighbors)) % MOD

    return (dp(0, 0) + 1) % MOD

