def count_beautiful_numbers(l: int, r: int) -> int:
    def is_beautiful(n: int) -> bool:
        prod = 1
        summ = 0
        temp = n
        while temp > 0:
            digit = temp % 10
            if digit == 0:
                return False
            prod *= digit
            summ += digit
            temp //= 10
        return prod % summ == 0

    return sum(is_beautiful(i) for i in range(l, r + 1))

def count_good_integers(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    MOD = 10**9 + 7
    def digit_sum(n: int) -> int:
        return sum(int(digit) for digit in str(n))
    def dp(i: int, tight: bool, current_sum: int) -> int:
        if i == len(num2):
            return 1 if min_sum <= current_sum <= max_sum else 0
        res = 0
        ub = int(num2[i]) if tight else 9
        for d in range(ub + 1):
            res += dp(i + 1, tight and d == ub, current_sum + d)
        return res % MOD
    low = dp(0, True, 0)
    high = dp(0, True, 0)
    for n in range(int(num1), int(num2) + 1):
        if min_sum <= digit_sum(n) <= max_sum:
            high -= 1
    return (high - low + MOD) % MOD

