def min_changes_for_semi_palindromes(s: str, k: int) -> int:
    def is_semi_palindrome(sub: str) -> bool:
        n = len(sub)
        if n < 2:
            return False
        for d in range(1, n // 2 + 1):
            if n % d == 0:
                groups = [sub[i:i+d] for i in range(0, n, d)]
                if groups == groups[::-1]:
                    return True
        return False

    def changes_to_semi_palindrome(sub: str) -> int:
        count = 0
        n = len(sub)
        for d in range(1, n // 2 + 1):
            if n % d == 0:
                groups = [sub[i:i+d] for i in range(0, n, d)]
                mid = n // 2
                for i in range(mid):
                    count += abs(ord(groups[i][i]) - ord(groups[mid-i-1][-i-1]))
                break
        return count

    if k == 1:
        return changes_to_semi_palindrome(s)

    dp = [[float('inf')] * (k+1) for _ in range(len(s)+1)]
    dp[0][0] = 0
    for i in range(1, len(s)+1):
        for j in range(1, k+1):
            for l in range(i-1, -1, -1):
                if is_semi_palindrome(s[l:i]):
                    dp[i][j] = min(dp[i][j], dp[l][j-1] + changes_to_semi_palindrome(s[l:i]))
                else:
                    dp[i][j] = min(dp[i][j], dp[l][j-1] + changes_to_semi_palindrome(s[l:i]) + (i-l))
    return dp[len(s)][k]

