MOD = 10**9 + 7
def count_stepping_numbers(low: str, high: str) -> int:
    def is_stepping(num: int) -> bool:
        num_str = str(num)
        if num_str[0] == '0':
            return False
        for i in range(1, len(num_str)):
            if abs(int(num_str[i]) - int(num_str[i-1])) != 1:
                return False
        return True

    @lru_cache(None)
    def dp(pos: int, last_digit: int, is_limit: bool) -> int:
        if pos == len(high):
            return 1
        max_digit = int(high[pos]) if is_limit else 9
        ans = 0
        for digit in range(max_digit + 1):
            if (last_digit == -1 and digit != 0) or (abs(digit - last_digit) == 1):
                ans = (ans + dp(pos + 1, digit, is_limit and digit == max_digit)) % MOD
        return ans

    low_int = int(low)
    high_int = int(high)
    return (dp(0, -1, True) - dp(0, -1, False) + MOD) % MOD if low_int > 0 else dp(0, -1, True)

