def max_partitions_with_one_change(s: str, k: int) -> int:
    def count_distinct(prefix):
        return len(set(prefix))

    n = len(s)
    max_partitions = 0

    for i in range(n + 1):
        prefix = s[:i]
        remaining = s[i:]
        if count_distinct(prefix) <= k:
            max_partitions += 1
            break

    for i in range(1, n + 1):
        prefix = s[:i]
        changed_prefix = ''.join([char if j != i else 'a' for j, char in enumerate(s)])
        remaining = s[i:]
        if count_distinct(changed_prefix) <= k:
            max_partitions += 1
            break

    return max_partitions

def dice_sum_probability(n: int, dice_faces: List[int]) -> int:
