def min_sensor_cost(n: int, sections: List[int], sensor1: Tuple[int, int, int], sensor2: Tuple[int, int, int]) -> int:
    L1, C1, K1 = sensor1
    L2, C2, K2 = sensor2

    def min_sensors(length, L):
        if length == 0:
            return 0
        elif L == 0:
            return float('inf')
        else:
            return min(min_sensors(length, L - 1) + C1, min_sensors(length, L - 2) + C2)

    total_length = sum(sections)
    return min_sensors(total_length, L1) + min_sensors(total_length, L2)

def tic_tac_toe_winner(grid: List[List[int]]) -> str:
    takahashi_score = 0
    aoki_score = 0
    takahashi_turn = True

    while True:
        if takahashi_turn:
            max_value = float('-inf')
            best_move = None
            for i in range(3):
                for j in range(3):
                    if grid[i][j] > max_value and grid[i][j] % 2 != 0:
                        max_value = grid[i][j]
                        best_move = (i, j)
            takahashi_score += max_value
            grid[best_move[0]][best_move[1]] = -1
        else:
            min_value = float('inf')
            best_move = None
            for i in range(3):
                for j in range(3):
                    if grid[i][j] < min_value and grid[i][j] % 2 != 0:
                        min_value = grid[i][j]
                        best_move = (i, j)
            aoki_score += min_value
            grid[best_move[0]][best_move[1]] = 1

        if takahashi_win(grid):
            return 'Takahashi'
        if aoki_win(grid):
            return 'Aoki'
        if all(cell != 0 for row in grid for cell in row):
            if takahashi_score > aoki_score:
                return 'Takahashi'
            elif takahashi_score < aoki_score:
                return 'Aoki'
            else:
                return 'Draw'

    def takahashi_win(grid):
        return any(sum(row) == -3 for row in grid) or \
               any(sum(col) == -3 for col in zip(*grid)) or \
               grid[0][0] + grid[1][1] + grid[2][2] == -3 or \
               grid[0][2] + grid[1][1] + grid[2][0] == -3

    def aoki_win(grid):
        return any(sum(row) == 3 for row in grid) or \
               any(sum(col) == 3 for col in zip(*grid)) or \
               grid[0][0] + grid[1][1] + grid[2][2] == 3 or \
               grid[0][2] + grid[1][1] + grid[2][0] == 3

from typing import List, Tuple

def card_game_winner(n: int, cards: List[Tuple[int, int]]) -> str:
    from collections import defaultdict
    front_to_back = defaultdict(set)
    back_to_front = defaultdict(set)

    for i, (front, back) in enumerate(cards):
        front_to_back[front].add(i)
        back_to_front[back].add(i)

    visited = set()

    def can_win(player, current_card):
        nonlocal visited
        visited.add(current_card)
        opponent = 'Takahashi' if player == 'Aoki' else 'Aoki'

        for next_card in front_to_back[current_card[0]] | back_to_front[current_card[1]] - visited:
            if next_card != current_card:
                if player == 'Takahashi' and can_win(opponent, cards[next_card]):
                    return True
                elif player == 'Aoki' and not can_win(opponent, cards[next_card]):
                    return False
        return player == 'Takahashi'

    for start_card in range(n):
        if can_win('Takahashi', cards[start_card]):
            return 'Takahashi'
    return 'Aoki'

