def sum_of_subsequence_powers(nums: List[int], k: int) -> int:
    MOD = 10**9 + 7
    n = len(nums)
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(k + 1):
            dp[i][j] = dp[i - 1][j]
            if j >= nums[i - 1]:
                dp[i][j] += dp[i - 1][j - nums[i - 1]]
                dp[i][j] %= MOD

    return dp[n][k]

def count_arithmetic_subsequences(n: int, a: List[int]) -> List[int]:
    MOD = 998244353
    dp = [[{} for _ in range(n)] for _ in range(n)]
    count = [0] * n
    for r in range(n):
        for c in range(r + 1, n):
            diff = a[c] - a[r]
            if diff not in dp[r][c]:
                dp[r][c][diff] = 0
            if diff not in dp[r][c - 1]:
                dp[r][c - 1][diff] = 0
            dp[r][c][diff] += dp[r][c - 1][diff] + 1
            dp[r][c][diff] %= MOD
            count[c] += dp[r][c][diff]
            count[c] %= MOD
    return count[:n]

from itertools import permutations
def count_valid_permutations(n: int, requirements: List[List[int]]) -> int:
    MOD = 10**9 + 7
    perms = permutations(range(n))
    count = 0
    for perm in perms:
        valid = True
        for end_i, cnt_i in requirements:
            inversions = sum(perm[i] > perm[j] for i in range(end_i + 1) for j in range(i + 1, end_i + 1))
            if inversions != cnt_i:
                valid = False
                break
        if valid:
            count += 1
    return count % MOD

