            prefix = subs[:i]
            if len(set(prefix)) > k:
                break
            max_parts = max(max_parts, 1 + helper(subs[i:], k))
        return max_parts

    # Try changing each character to every other lowercase letter
    max_partitions = 0
    for i in range(len(s)):
        for j in range(97, 123):  # ASCII values for 'a' to 'z'
            new_s = s[:i] + chr(j) + s[i+1:] if ord(s[i]) != j else s
            max_partitions = max(max_partitions, helper(new_s, k))

    return max_partitions

