def dice_sum_probability(n: int, dice_faces: List[int]) -> int:
    MOD = 998244353
    target = 10
    dp = [[0] * (target + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        max_face = min(dice_faces[i - 1], target)
        for j in range(target + 1):
            dp[i][j] = dp[i - 1][j]
            if j >= 1:
                dp[i][j] += dp[i - 1][j - 1]
            if j > max_face:
                dp[i][j] -= dp[i - 1][j - max_face - 1]
            dp[i][j] %= MOD

    return dp[n][target]

