def min_cost_to_achieve_goal(n: int, k: int, p: int, plans: List[Tuple[int, List[int]]]) -> int:
    target = [p] * k
    max_heap = []
    remaining_plans = set(range(n))
    cost = 0

    while remaining_plans:
        for i in list(remaining_plans):
            _, increase = plans[i]
            if sum(increase) > 0:
                heapq.heappush(max_heap, (-sum(increase), i, increase[:]))
                increase.pop(0)
                if len(increase) == 0:
                    remaining_plans.remove(i)

        if not remaining_plans:
            return cost

        _, index, inc = heapq.heappop(max_heap)
        cost += plans[index][0]
        for j in range(k):
            if plans[index][1][j] > 0:
                target[j] -= plans[index][1][j]
                plans[index][1][j] = 0

        if all(x >= y for x, y in zip(target, plans[index][1])):
            return cost

    return -1

def min_sensor_cost(n: int, sections: List[int], sensor1: Tuple[int, int, int], sensor2: Tuple[int, int, int]) -> int:
    L1, C1, K1 = sensor1
    L2, C2, K2 = sensor2
    dp = [[float('inf')] * (sum(sections) + 1) for _ in range(n + 1)]
    dp[0][0] = 0
    for i in range(1, n + 1):
        prefix_sum = 0
        for j in range(len(sections[:i])):
            prefix_sum += sections[j]
            for k in range(prefix_sum + 1):
                for l1 in range(min(k // L1 + 1, K1 + 1)):
                    for l2 in range(min((k - l1 * L1) // L2 + 1, K2 + 1)):
                        if k >= l1 * L1 + l2 * L2:
                            dp[i][k] = min(dp[i][k], dp[i - 1][k - l1 * L1 - l2 * L2] + l1 * C1 + l2 * C2)
    return dp[n][sum(sections)] if dp[n][sum(sections)] != float('inf') else -1

