def min_spanning_tree_mod_k(n: int, m: int, k: int, edges: List[Tuple[int, int, int]]) -> int:
    parent = [i for i in range(n + 1)]
    rank = [0] * (n + 1)

    def find(node):
        if parent[node] != node:
            parent[node] = find(parent[node])
        return parent[node]

    def union(u, v):
        root_u = find(u)
        root_v = find(v)
        if root_u != root_v:
            if rank[root_u] > rank[root_v]:
                parent[root_v] = root_u
            elif rank[root_u] < rank[root_v]:
                parent[root_u] = root_v
            else:
                parent[root_v] = root_u
                rank[root_u] += 1

    edges.sort(key=lambda x: x[2])
    total_cost = 0

    for u, v, w in edges:
        if find(u) != find(v):
            union(u, v)
            total_cost = (total_cost + w) % k

    return total_cost

def min_operations_to_match_grids(H: int, W: int, A: List[List[int]], B: List[List[int]]) -> Optional[int]:
    if A == B:
        return 0
    visited = set()
    def dfs(x, y, steps):
        nonlocal min_steps
        if (x, y) in visited:
            return
        visited.add((x, y))
        if A[x][y] != B[x][y]:
            return
        if steps >= min_steps:
            return
        if x > 0:
            dfs(x - 1, y, steps + 1)
        if x < H - 1:
            dfs(x + 1, y, steps + 1)
        if y > 0:
            dfs(x, y - 1, steps + 1)
        if y < W - 1:
            dfs(x, y + 1, steps + 1)
        visited.remove((x, y))
    min_steps = float('inf')
    for i in range(H):
        for j in range(W):
            dfs(i, j, 0)
    return min_steps if min_steps != float('inf') else None

