def divide_into_good_sequences(L: int, R: int) -> List[Tuple[int, int]]:
    result = []
    current_start = L
    while current_start < R:
        next_power_of_two = 1 << (current_start.bit_length())
        if current_start + next_power_of_two <= R:
            result.append((current_start, current_start + next_power_of_two))
            current_start += next_power_of_two
        else:
            result.append((current_start, R))
