    return result

def tic_tac_toe_winner(grid: List[List[int]]) -> str:
    takahashi_score = 0
    aoki_score = 0
    takahashi_turn = True

    while True:
        available_cells = [(i, j) for i in range(3) for j in range(3) if grid[i][j] != 'R' and grid[i][j] != 'B']
        if not available_cells:
            break

        if takahashi_turn:
            max_value = max(available_cells, key=lambda x: grid[x[0]][x[1]])
            grid[max_value[0]][max_value[1]] = 'R'
            takahashi_score += grid[max_value[0]][max_value[1]]
        else:
            min_value = min(available_cells, key=lambda x: grid[x[0]][x[1]])
            grid[min_value[0]][min_value[1]] = 'B'
            aoki_score += grid[min_value[0]][min_value[1]]

        takahashi_turn = not takahashi_turn

    if check_win_condition(grid, 'R'):
        return 'Takahashi'
    elif check_win_condition(grid, 'B'):
        return 'Aoki'
    else:
        return 'Draw'

def check_win_condition(grid: List[List[str]], player: str) -> bool:
    directions = [(0, 1), (1, 0), (1, 1), (1, -1)]

    for i in range(3):
        for j in range(3):
            if grid[i][j] == player:
                for dx, dy in directions:
                    count = 1
                    for k in range(1, 3):
                        ni, nj = i + dx * k, j + dy * k
                        if 0 <= ni < 3 and 0 <= nj < 3 and grid[ni][nj] == player:
                            count += 1
                        else:
                            break
                    if count == 3:
                        return True

    return False

def card_game_winner(n: int, cards: List[Tuple[int, int]]) -> str:
    # Create a dictionary to store the count of each front and back number
    counts = {}
    for front, back in cards:
        if front in counts:
            counts[front] += 1
        else:
            counts[front] = 1
        if back in counts:
            counts[back] += 1
        else:
            counts[back] = 1

    # Count the number of cards with odd counts
    odd_count_cards = sum(1 for count in counts.values() if count % 2 != 0)

    # If there is an odd number of cards with odd counts, Takahashi wins; otherwise, Aoki wins
    return 'Takahashi' if odd_count_cards % 2 != 0 else 'Aoki'

