def min_team_switches(people: List[Tuple[int, int]]) -> int:
    team_strengths = [0] * 4
    team_counts = [0] * 4
    for team, strength in people:
        team_strengths[team] += strength
        team_counts[team] += 1

    target_strength = sum(team_strengths) // 3
    if target_strength * 3 != sum(team_strengths):
        return -1

    switches = 0
    while True:
        balanced = True
        for team in range(1, 4):
            if team_strengths[team] > target_strength:
                for other_team in range(1, 4):
                    if other_team != team and team_strengths[other_team] < target_strength:
                        diff = min(team_strengths[team] - target_strength, target_strength - team_strengths[other_team])
                        team_strengths[team] -= diff
                        team_strengths[other_team] += diff
                        switches += 1
                        balanced = False
                        break
                if not balanced:
                    break
            elif team_strengths[team] < target_strength:
                for other_team in range(1, 4):
                    if other_team != team and team_strengths[other_team] > target_strength:
                        diff = min(target_strength - team_strengths[team], team_strengths[other_team] - target_strength)
                        team_strengths[team] += diff
                        team_strengths[other_team] -= diff
                        switches += 1
                        balanced = False
                        break
                if not balanced:
                    break
        if balanced:
            break

    return switches

