        return 0 <= x < H and 0 <= y < W and grid[x][y] == '.' and (x, y) not in visited

    def dfs(x: int, y: int, steps: int, visited: set) -> int:
        if steps == K + 1:
            return 1
        count = 0
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if is_valid_move(nx, ny, visited):
                visited.add((nx, ny))
                count += dfs(nx, ny, steps + 1, visited)
                visited.remove((nx, ny))
        return count

    total_paths = 0
    for i, j in product(range(H), range(W)):
        if grid[i][j] == '.':
            total_paths += dfs(i, j, 1, {(i, j)})
    return total_paths

