def card_game_winner(n: int, m: int, l: int, takahashi_cards: List[int], aoki_cards: List[int], table_cards: List[int]) -> str:
    def can_win(cards, opponent_cards, table):
        if not cards:
            return False
        sorted_cards = sorted(cards)
        for card in sorted_cards[::-1]:
            if any(opponent_card > card for opponent_card in opponent_cards):
                for i, t_card in enumerate(table):
                    if t_card < card:
                        table[i] = float('inf')
                        if can_win(cards[:i] + cards[i+1:], opponent_cards, table):
                            return True
                        table[i] = t_card
            else:
                for i, t_card in enumerate(table):
                    if t_card < card:
                        table[i] = float('inf')
                        if can_win(cards[:i] + cards[i+1:], opponent_cards, table):
                            return True
                        table[i] = t_card
        return False
    takahashi_turn = True
    while n > 0 or m > 0 or l > 0:
        if takahashi_turn:
            if can_win(takahashi_cards, aoki_cards, table_cards):
                return 'Takahashi'
            n -= 1
            takahashi_cards.append(float('inf'))
        else:
            if can_win(aoki_cards, takahashi_cards, table_cards):
                return 'Aoki'
            m -= 1
            aoki_cards.append(float('inf'))
        takahashi_turn = not takahashi_turn
    return 'Takahashi'

