    current_position = 1
    for i in range(n):
        if visited[i]:
            continue
        cycle_size = 0
        x = i
        while not visited[x]:
            visited[x] = True
            x = sorted_indices[permutation[x]] - 1
            cycle_size += 1
        if cycle_size > 0:
            cost += cycle_size * (cycle_size - 1) // 2
