def count_distinct_parenthesis_sequences(n: int, s: str) -> int:
    MOD = 998244353

    @lru_cache(None)
    def dp(i: int, j: int, rev: bool) -> int:
        if i > j:
            return 1
        if i == j:
            return 1 if s[i] == ('(' if not rev else ')') else 0

        count = 0
        for k in range(i, j + 1):
            if (s[k] == '(' if not rev else ')') and ((k == i or s[k - 1] != s[k]) if not rev else (k == i or s[k - 1] != ('(' if rev else ')'))):
                if k + 1 <= j:
                    count += dp(k + 1, j, not rev)
                if i <= k - 1:
                    count += dp(i, k - 1, not rev)
