def max_product_subsequence(nums: List[int], k: int, limit: int) -> int:
    n = len(nums)
    dp = [[[-1] * 2 for _ in range(n + 1)] for _ in range(k + 1)]

    def helper(i, remaining_sum, last_picked):
        if i >= n:
            return 1 if remaining_sum == k else -1
        if dp[abs(remaining_sum)][i][last_picked] != -1:
            return dp[abs(remaining_sum)][i][last_picked]

        result = -1
        pick = -1
        if last_picked == 0:
            pick = nums[i] * helper(i + 1, remaining_sum + nums[i], 1)
        else:
            pick = helper(i + 1, remaining_sum - nums[i], 0)

        dont_pick = helper(i + 1, remaining_sum, last_picked)

        result = max(pick, dont_pick)
        dp[abs(remaining_sum)][i][last_picked] = result
        return result

    result = helper(0, 0, 0)
    return result if result > 0 else -1

def kth_alternating_permutation(n: int, k: int) -> List[int]:
    if k > factorial(n) // 2:
        return []

    def generate_alternating_permutations(nums, current_perm):
        if len(current_perm) == n:
            permutations.append(current_perm[:])
            return
        for i in nums:
            if not current_perm or (current_perm[-1] % 2 != i % 2):
                generate_alternating_permutations(nums - {i}, current_perm + [i])

    permutations = []
    generate_alternating_permutations(set(range(1, n + 1)), [])

    return permutations[k - 1]

