def solve_grid(n: int, r: str, c: str) -> Optional[List[str]]:
    def backtrack(grid, row):
        if row == n:
            return True
        used_chars = {'A', 'B', 'C'}
        for col in range(n):
            if grid[row][col] != '.':
                continue
            if r[row] != '.' and r[row] != grid[row][col]:
                continue
            if c[col] != '.' and c[col] != grid[row][col]:
                continue
            if grid[row].count('.') > 1 or ''.join(row[col] for row in grid).count('.') > 1:
                continue
            grid[row] = grid[row][:col] + r[row] + grid[row][col+1:] if r[row] != '.' else grid[row]
            if backtrack(grid, row + 1):
                return True
            grid[row] = grid[row][:col] + '.' + grid[row][col+1:] if r[row] != '.' else grid[row]
        return False

    initial_grid = [['.'] * n for _ in range(n)]
    if not backtrack(initial_grid, 0):
        return None
    return [''.join(row) for row in initial_grid]

