def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    def tile_bounds(i, j, k):
        if i % 2 == j % 2:
            return (i * K, (i + 1) * K), (j * K + k, j * K + k + 1)
        else:
            return ((i * K + k, i * K + k + 1), (j * K, (j + 1) * K))

    def tile_center(i, j, k):
        bounds = tile_bounds(i, j, k)
        return ((bounds[0][0] + bounds[0][1]) / 2, (bounds[1][0] + bounds[1][1]) / 2)

    def manhattan_distance(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    start_tile_i = S_x // K
    start_tile_j = S_y // K
    start_tile_k = (S_y % K) if start_tile_i % 2 == start_tile_j % 2 else (K - (S_y % K))

    target_tile_i = T_x // K
    target_tile_j = T_y // K
    target_tile_k = (T_y % K) if target_tile_i % 2 == target_tile_j % 2 else (K - (T_y % K))

    start_center = tile_center(start_tile_i, start_tile_j, start_tile_k)
    target_center = tile_center(target_tile_i, target_tile_j, target_tile_k)

    return manhattan_distance(start_center, target_center)

def count_good_arrays(n: int, m: int, k: int) -> int:
