    if k >= n:
        return 0

    dp = [[[0] * (k + 1) for _ in range(m + 1)] for _ in range(n + 1)]

    for i in range(1, m + 1):
        dp[1][i][0] = 1

    for length in range(2, n + 1):
        for prev in range(1, m + 1):
            for eq_pairs in range(k + 1):
                if eq_pairs > 0:
                    dp[length][prev][eq_pairs] += dp[length - 1][prev][eq_pairs - 1]
                dp[length][prev][eq_pairs] %= MOD
                for current in range(1, m + 1):
                    if current != prev:
                        dp[length][current][eq_pairs] += dp[length - 1][prev][eq_pairs]
                        dp[length][current][eq_pairs] %= MOD

    result = sum(dp[n][j][k] for j in range(1, m + 1)) % MOD

    return result

