def min_spanning_tree_mod_k(n: int, m: int, k: int, edges: List[Tuple[int, int, int]]) -> int:
    from heapq import heappop, heappush
    from collections import defaultdict, deque
    parent = [i for i in range(n + 1)]
    rank = [0] * (n + 1)
    mod_cost = 0

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rootX = find(x)
        rootY = find(y)
        if rootX != rootY:
            if rank[rootX] > rank[rootY]:
                parent[rootY] = rootX
            elif rank[rootX] < rank[rootY]:
                parent[rootX] = rootY
            else:
                parent[rootY] = rootX
                rank[rootX] += 1
            nonlocal mod_cost
            mod_cost = (mod_cost + edges[edges.index((x, y, edges[-1][2]))][2]) % k

    edges.sort(key=lambda x: x[2])
    for u, v, w in edges:
        union(u, v)

    return mod_cost

def min_operations_to_match_grids(H: int, W: int, A: List[List[int]], B: List[List[int]]) -> Optional[int]:
    count = 0
    visited = set()
    directions = [(0, 1), (1, 0)]  # Right and Down

    def dfs(x, y):
        nonlocal count
        stack = [(x, y)]
        while stack:
            cx, cy = stack.pop()
            if (cx, cy) in visited:
                continue
            visited.add((cx, cy))
            if A[cx][cy] != B[cx][cy]:
                found = False
                for dx, dy in directions:
                    nx, ny = cx + dx, cy + dy
                    if 0 <= nx < H and 0 <= ny < W and (nx, ny) not in visited:
                        if A[nx][ny] == B[cx][cy]:
                            stack.append((nx, ny))
                            found = True
                            break
                if not found:
                    return None
            else:
                count += 1
        return count

    for i in range(H):
        for j in range(W):
            if (i, j) not in visited:
                result = dfs(i, j)
                if result is None:
                    return None
    return count // 2

