def min_weight_hamiltonian_walk(n: int, m: int, edges: List[Tuple[int, int, int]]) -> Optional[int]:
    # Create adjacency matrix
    adj_matrix = [[inf] * n for _ in range(n)]
    for u, v, w in edges:
        adj_matrix[u - 1][v - 1] = w

    # Initialize memoization table
    memo = {}

    def hamiltonian_path(start: int, visited: tuple) -> int:
        if visited in memo:
            return memo[visited]
        if sum(visited) == (1 << n) - 1:
            return adj_matrix[start][0] if adj_matrix[start][0] != inf else inf

        min_cost = inf
        for next_vertex in range(n):
            if not visited[next_vertex] and adj_matrix[start][next_vertex] != inf:
                new_visited = visited[:next_vertex] + (1 << next_vertex,) + visited[next_vertex + 1:]
                cost = adj_matrix[start][next_vertex] + hamiltonian_path(next_vertex, new_visited)
                min_cost = min(min_cost, cost)
        memo[visited] = min_cost
        return min_cost

    # Find the minimum weight Hamiltonian walk starting from any vertex
    best_cost = inf
    for start in range(n):
        visited = (1 << start,) + (0,) * (n - 1)
        cost = hamiltonian_path(start, visited)
        best_cost = min(best_cost, cost)

    return best_cost if best_cost < inf else None

