def count_arithmetic_subsequences(n: int, a: List[int]) -> List[int]:
    MOD = 998244353
    result = [0] * n
    dp = [[{} for _ in range(n)] for _ in range(n)]

    for length in range(1, n + 1):
        for end in range(length - 1, n):
            for start in range(end):
                diff = a[end] - a[start]
                if (start, diff) in dp[end]:
                    dp[end][start][diff] += 1
                    result[length - 1] = (result[length - 1] + dp[end][start][diff]) % MOD
                elif (end, diff) in dp[start]:
                    dp[start][end][diff] += 1
                    result[length - 1] = (result[length - 1] + dp[start][end][diff]) % MOD
