def count_valid_permutations(n: int, requirements: List[List[int]]) -> int:
    MOD = 10**9 + 7
    factorial = [1] * (n + 1)
    inv_factorial = [1] * (n + 1)
    for i in range(1, n + 1):
        factorial[i] = factorial[i - 1] * i % MOD
        inv_factorial[i] = pow(factorial[i], MOD - 2, MOD)

    def inversions(perm):
        return sum(perm[i] > perm[j] for i in range(len(perm)) for j in range(i + 1, len(perm)))

    def choose(k, m):
        return factorial[k] * inv_factorial[m] * inv_factorial[k - m] % MOD

    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for _, cnt in reversed(requirements):
        new_dp = [[0] * (n + 1) for _ in range(n + 1)]
        for end in range(n + 1):
            for inv in range(end + 1):
                if inv == cnt:
                    new_dp[end][inv] += dp[end][inv]
                elif inv < cnt:
                    new_dp[end][inv] += dp[end][inv + 1]
        dp = new_dp

    result = dp[n][0]
    return result

def minimum_shipping_dissatisfaction(n: int, k: int, x: int, order_days: List[int]) -> int:
    dissatisfactions = []
    current_batch_start = order_days[0]
    current_batch_size = 1
    for i in range(1, n):
        if current_batch_size >= k or order_days[i] - order_days[current_batch_start - 1] > x:
            for j in range(current_batch_start - 1, i):
                dissatisfactions.append((order_days[j] - order_days[j - 1]) * (i - j))
            current_batch_start = order_days[i]
            current_batch_size = 1
        else:
            current_batch_size += 1
    for j in range(current_batch_start - 1, n):
        dissatisfactions.append((order_days[j] - order_days[j - 1]) * (n - j))
    return sum(dissatisfactions)

def min_ng_list_size(n: int, product_names: List[str]) -> int:
