                graph[product_names[j]].add(product_names[i])

    def dfs(node, visited):
        stack = [node]
        while stack:
            node = stack.pop()
            if node not in visited:
                visited.add(node)
                for neighbor in graph[node]:
                    stack.append(neighbor)

    components = 0
    visited = set()
    for name in product_names:
        if name not in visited:
            dfs(name, visited)
            components += 1

    return components

