def max_production_capacity(n: int, x: int, machines: List[Tuple[int, int, int, int]]) -> int:
    # Initialize variables to store the best capacities found for each process
    best_capacities = [float('inf')] * n

    # Iterate over all possible combinations of machine counts for each process
    for proc in range(n):
        min_prod = float('inf')
        total_cost = 0
        for s_count in range((x // machines[proc][1]) + 1):
            for t_count in range((x // machines[proc][3]) + 1):
                cost = s_count * machines[proc][1] + t_count * machines[proc][3]
                if cost > x:
                    break
                prod = s_count * machines[proc][0] + t_count * machines[proc][2]
                if prod < min_prod:
                    min_prod = prod
                    total_cost = cost
        best_capacities[proc] = min_prod

    # Return the minimum of the best capacities found
    return min(best_capacities)

def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def dfs(x, y, k, visited):
        if k == 0:
            return 1
        visited.add((x, y))
        paths = 0
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < H and 0 <= ny < W and grid[nx][ny] == '.' and (nx, ny) not in visited:
                paths += dfs(nx, ny, k - 1, visited)
        visited.remove((x, y))
        return paths

    result = 0
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '.' and (i, j) != (0, 0):  # Ensure we do not start from the origin twice
                result += dfs(i, j, K, set())
    return result

def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    MOD = 998244353
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def dfs(row, col, prev_digit):
        nonlocal count
        if row == H:
            count += 1
            return
        if col == W:
            dfs(row + 1, 0, prev_digit)
            return
        if grid[row][col] != '?':
            if grid[row][col] == str(prev_digit):
                dfs(row, col + 1, prev_digit)
            return

        for next_digit in range(1, 4):
            if next_digit != prev_digit:
                grid[row] = grid[row][:col] + str(next_digit) + grid[row][col+1:]
                dfs(row, col + 1, next_digit)
                grid[row] = grid[row][:col] + '?' + grid[row][col+1:]  # Backtrack

    count = 0
    dfs(0, 0, 0)
    return count % MOD

def card_game_winner(n: int, m: int, l: int, takahashi_cards: List[int], aoki_cards: List[int], table_cards: List[int]) -> str:
    takahashi_turn = True
    while takahashi_cards or aoki_cards or table_cards:
        if takahashi_turn:
            if takahashi_cards:
                played_card = max(takahashi_cards)
                takahashi_cards.remove(played_card)
                if table_cards:
                    for i, card in enumerate(table_cards):
                        if card < played_card:
                            takahashi_cards.append(card)
                            del table_cards[i]
                            break
            else:
                return 'Aoki'
        else:
            if aoki_cards:
                played_card = max(aoki_cards)
                aoki_cards.remove(played_card)
                if table_cards:
