def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    MOD = 998244353

    @lru_cache(None)
    def dp(i: int, j: int) -> int:
        if i == M:
            return 1
        if j == N:
            return 0
        res = dp(i, j + 1)
        if X[i] == X[j % M]:
            res += dp(i + 1, j + 1)
        return res % MOD

