def count_good_string_replacements(n: int, k: int, s: str) -> int:
    MOD = 998244353

    def dp(i, j, last_char, cnt):
        if i == n:
            return 1 if cnt >= k else 0
        if (i, j, last_char, cnt) in memo:
            return memo[(i, j, last_char, cnt)]

        res = 0
        if s[i] == '?' or s[i] == last_char:
            res += dp(i + 1, j, s[i], cnt)
            res %= MOD
        if j > 0 and last_char != s[i]:
            res += dp(i + 1, j - 1, '?', cnt + 1)
            res %= MOD
        if s[i] != '?':
            res += dp(i + 1, j + 1, s[i], cnt)
            res %= MOD

        memo[(i, j, last_char, cnt)] = res
        return res

    memo = {}
    return dp(0, 0, '?', 0)

def can_reach_end(n: int, m: int, a: int, b: int, bad_intervals: List[Tuple[int, int]]) -> bool:
    visited = set()
    queue = [1]
    while queue:
        current = queue.pop(0)
        if current == n:
            return True
        if current in visited:
            continue
        visited.add(current)
        for jump in range(a, b + 1):
            next_square = current + jump
            if next_square > n or (current + jump - 1, current + jump) in bad_intervals:
                continue
            queue.append(next_square)
    return False

