def max_alkane_vertices(n: int, edges: List[Tuple[int, int]]) -> int:
    # Create an adjacency list representation of the graph
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Helper function to perform DFS and check for alkane properties
    def dfs(node, parent, visited, degree_count):
        visited.add(node)
        degree = len(adj[node])
        if degree not in [1, 4]:
            return False
        if degree == 4:
            degree_count[4] += 1
        for neighbor in adj[node]:
            if neighbor != parent and neighbor not in visited:
                if not dfs(neighbor, node, visited, degree_count):
                    return False
        return True

    # Check if there's at least one vertex of degree 4
    degree_count = {1: 0, 4: 0}
    for i in range(1, n + 1):
        if len(adj[i]) == 4:
            degree_count[4] += 1
            break
    if degree_count[4] == 0:
        return -1

    # Start DFS from any node
    visited = set()
    for i in range(1, n + 1):
        if i not in visited and dfs(i, -1, visited, degree_count):
            return len(visited)
    return -1

