import heapq

def max_shortest_distance(n: int, m: int, k: int, edges: List[Tuple[int, int]]) -> int:
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append((v, 0))

    def dijkstra(start):
        dist = [float('inf')] * (n + 1)
        dist[start] = 0
        pq = [(0, start)]
        while pq:
            current_dist, u = heapq.heappop(pq)
            if current_dist > dist[u]:
                continue
            for v, weight in graph[u]:
                new_dist = current_dist + weight
                if new_dist < dist[v]:
                    dist[v] = new_dist
                    heapq.heappush(pq, (new_dist, v))
        return dist[n]

    original_dist = dijkstra(1)

    for _ in range(k):
        min_increase = float('inf')
        for u, v in edges:
            if graph[u][0][1] == 0:
                graph[u][0] = (v, 1)
                dist_u_to_v = dijkstra(1)
                if dist_u_to_v > original_dist and dist_u_to_v - original_dist < min_increase:
                    min_increase = dist_u_to_v - original_dist
                graph[u][0] = (v, 0)

        if min_increase == float('inf'):
            break

        original_dist += min_increase

    return original_dist - 1

def sum_of_subarray_powers(n: int, k: int, a: List[int]) -> int:
    MOD = 998244353
    total_sum = 0
    for start in range(n):
        current_sum = 0
        for end in range(start, n):
            current_sum = (current_sum + a[end]) % MOD
            total_sum = (total_sum + pow(current_sum, k, MOD)) % MOD
    return total_sum

