def min_cost_to_sort(n: int, permutation: List[int]) -> int:
    def bubble_sort_with_cost(permutation):
        cost = 0
        n = len(permutation)
        for i in range(n):
            for j in range(0, n-i-1):
                if permutation[j] > permutation[j+1]:
