def kth_alternating_permutation(n: int, k: int) -> List[int]:
    if k > factorial(n) // 2:
        return []
    if n % 2 == 0:
        evens = list(range(2, n+1, 2))
        odds = list(range(1, n+1, 2))
    else:
        evens = list(range(2, n, 2)) + [n]
        odds = list(range(1, n, 2))
    alt_perms = []
    def dfs(path, evens, odds):
        if len(path) == n:
            alt_perms.append(path)
            return
        if evens:
            dfs(path + [evens.pop()], evens, odds)
        if odds:
            dfs(path + [odds.pop()], evens, odds)
    dfs([], evens[:], odds[:])
    alt_perms.sort()
    return alt_perms[k-1]

