def stream_to_input(symbols):
    nums = []
    i = 0
    while i < len(symbols):
        if symbols[i] == 0:
            nums.append(-1)
        else:
            nums.append(1)
        i += 1
    return (nums, 1)

def oracle(input):
    nums = input[0]
    k = input[1]
    n = len(nums)
    prefix = 0
    best = None
    min_pref = {}
    min_idx = {}
    min_pref[0] = 0
    min_idx[0] = 0
    for i in range(1, n + 1):
        prefix += nums[i - 1]
        r = i % k
        if r in min_pref:
            cand = prefix - min_pref[r]
            if best is None or cand > best:
                best = cand
            if prefix < min_pref[r]:
                min_pref[r] = prefix
                min_idx[r] = i
        else:
            min_pref[r] = prefix
            min_idx[r] = i
    return best

